import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic 2D benchmark function exhibiting specific ELA features.
    This function uses a combination of a modified Rosenbrock-like valley,
    a skewed term based on x[0], and a periodic component with interaction.

    Formula:
    f(x) = valley_term + skew_term + periodic_term;

    where:
    - valley_term = (1 - x[0])**2 + 100 * (x[1] - x[0]**2)**2 / 200;
    - skew_term = 0.6 * np.exp(x[0] * 0.6)  + 0.1*x[0]**3;
    - periodic_term = 0.15 * np.sin(4 * x[0] + 4 * x[1]) + 0.05 * x[0]*x[1];

    """

    valley_term = (1 - x[0])**2 + 100 * (x[1] - x[0]**2)**2 / 200;
    skew_term = 0.6 * np.exp(x[0] * 0.6)  + 0.1*x[0]**3;
    periodic_term = 0.15 * np.sin(4 * x[0] + 4 * x[1]) + 0.05 * x[0]*x[1];

    return valley_term + skew_term + periodic_term

